const triggerData = $('Trigger').first().json;
const expectedKeys = triggerData.changed_keys || [];

let raw = $json.output || '';
raw = raw.replace(/```json|```/g, '').trim();

const currentAttempt = $json.attempt ?? 1;
const maxAttempts = $json.max_attempts ?? 3;

const result = {
  valid: false,
  parsed: null,
  errors: [],
  retry_message: '',
  attempt: currentAttempt,
  max_attempts: maxAttempts,
};

let parsed;

try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) {
    throw new Error('No JSON object found in output');
  }

  parsed = JSON.parse(match[0]);
} catch (e) {
  result.errors.push(`Invalid JSON: ${e.message}`);
  result.retry_message =
    `Your previous response was invalid. Return only a valid JSON object with exactly these top-level keys: ${expectedKeys.join(', ')}.`;
  return [{ json: result }];
}

if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
  result.errors.push('Parsed output is not a top-level JSON object');
}

const actualKeys = Object.keys(parsed || {});
const missingKeys = expectedKeys.filter(k => !actualKeys.includes(k));
const extraKeys = actualKeys.filter(k => !expectedKeys.includes(k));

if (missingKeys.length) result.errors.push(`Missing keys: ${missingKeys.join(', ')}`);
if (extraKeys.length) result.errors.push(`Unexpected keys: ${extraKeys.join(', ')}`);

for (const key of expectedKeys) {
  if (key in (parsed || {}) && typeof parsed[key] !== 'string') {
    result.errors.push(`Key "${key}" must contain a string value`);
  }
}

if (result.errors.length === 0) {
  result.valid = true;
  result.parsed = parsed;
} else {
  result.retry_message =
    `Your previous response did not match the required schema.\n` +
    `Expected top-level keys: ${expectedKeys.join(', ')}.\n` +
    `Errors: ${result.errors.join(' | ')}.\n` +
    `Return only a valid JSON object with exactly those top-level keys and string values.`;
}

return [{ json: result }];

