const triggerData = $('Trigger').first().json;

const changedKeys = triggerData.changed_keys || [];
const changedValues = triggerData.changed_values || {};
const actualValues = triggerData.original_values || {};

const dbSource = $json.payload ?? $json;

const fields = changedKeys.map((key) => ({
  key,
  old_value: actualValues[key] ?? null,
  new_value: changedValues[key] ?? null,
  db_value: dbSource?.[key] ?? null,
}));

return [
  {
    json: {
      fields
    }
  }
];

const triggerData = $('Trigger').first().json;
const changedKeys = triggerData.changed_keys || [];
const fields = $('Prepare Fields').first().json.fields;
const language = triggerData.language || 'target language';

const retryPrompt = `
Your previous response was invalid.

Validation errors:
${($json.errors || []).join('\n')}

You must regenerate the entire JSON object from the original input data.
Do not only fix the reported missing or invalid keys.
Re-process every required field again.

Target language: ${language}

Requirements:
- return exactly these top-level keys: ${changedKeys.join(', ')}
- regenerate all values again from the input data
- every value must be a string
- every value must be written in ${language}
- do not leave any value in the wrong language
- do not include extra keys
- do not include markdown
- do not include explanations

Original input data:
${JSON.stringify(fields, null, 2)}
`;

return [{
  json: {
    ...$json,
    retry_user_message: retryPrompt
  }
}];

